95: // GetResourceName extracts the name of the resource from a method's input message.
96: // For example, for `CreateInstanceRequest`, it would return "Instance".
97: func GetResourceName(method *api.Method) (string, error) {
98: 	if method.InputType == nil {
99: 		return "", fmt.Errorf("method input type is nil")
100: 	}
101: 	for _, f := range method.InputType.Fields {
102: 		if msg := f.MessageType; msg != nil && msg.Resource != nil {
103: 			return msg.Name, nil
104: 		}
105: 	}
