109: // GetResourceForMethod finds the `api.Resource` definition associated with a method.
110: // This is a crucial function for linking a method to the resource it operates on.
111: func GetResourceForMethod(method *api.Method, model *api.API) *api.Resource {
112: 	if method.InputType == nil {
113: 		return nil
114: 	}
115: 
116: 	// Strategy 1: For `Create` and `Update`, the request message usually contains
117: 	// a field that *is* the resource message. This message is annotated with `(google.api.resource)`.
118: 	for _, f := range method.InputType.Fields {
119: 		if msg := f.MessageType; msg != nil && msg.Resource != nil {
120: 			return msg.Resource
121: 		}
122: 	}
123: 
124: 	// Strategy 2: For `Get`, `Delete`, and `List`, the request message has a `name`
125: 	// or `parent` field with a `(google.api.resource_reference)`.
126: 	var resourceType string
127: 	for _, field := range method.InputType.Fields {
128: 		if (field.Name != "name" && field.Name != "parent") || field.ResourceReference == nil {
129: 			continue
130: 		}
131: 		// For collection methods (like List), the reference is to the parent,
132: 		// and the resource we care about is the `child_type`.
133: 		if field.ResourceReference.ChildType != "" {
134: 			resourceType = field.ResourceReference.ChildType
135: 		} else {
136: 			resourceType = field.ResourceReference.Type
137: 		}
138: 		break
139: 	}
140: 
141: 	if resourceType == "" {
142: 		return nil
143: 	}
144: 
145: 	// Use the API model's indexed maps for an efficient lookup.
146: 	for _, r := range model.ResourceDefinitions {
147: 		if r.Type == resourceType {
148: 			return r
149: 		}
150: 	}
151: 
152: 	// Also check resources defined on messages directly.
153: 	for _, m := range model.Messages {
154: 		if m.Resource != nil && m.Resource.Type == resourceType {
155: 			return m.Resource
156: 		}
157: 	}
